        vm.prank(address(attacker)); 
        governmental.invest{value: 1 ether}();
        skip(ONE_MINUTE + 1);
    }

    function testResetInvestmentDespiteTransferFailure() public {
        // Capture initial states
        address initialLastInvestor = governmental.lastInvestor();
        uint256 initialJackpot = governmental.jackpot();
        uint256 initialContractBalance = address(governmental).balance;

        // Trigger reset transaction
        vm.prank(address(attacker));
        governmental.resetInvestment();

        // Verify state reset even after failed transfer
        assertEq(governmental.lastInvestor(), address(0), "Investor not reset");
        assertEq(governmental.jackpot(), 1 ether, "Jackpot not reset to 1 ether");

